window.OPOSSUM_FOOT_GAP_DATA["MI"] = [{"category":1,"rule":"Permanently affix name+address, MI driver's licence no., or DNR Sportcard no. in legible English to any trap","deadline":null,"source":"https://www.michigan.gov/dnr/managing-resources/laws/regulations/fur-harvester"},{"category":2,"rule":"Bobcat, otter, fisher, marten: free kill tag before harvest, swapped for DNR seal at registration; no buy/sell of those pelts without seal unless tanned/processed; incidental otter in beaver season (through Apr 30) counts toward bag limit","deadline":"Incidental otter registration by May 5, 2027","source":"https://www.michigan.gov/dnr/managing-resources/laws/regulations/fur-harvester"},{"category":3,"rule":"Per-animal harvest reporting is embedded in the pelt tagging/sealing requirement — see the Category 2 entry for this state","deadline":"Incidental otter registration by May 5, 2027","source":"https://www.michigan.gov/dnr/managing-resources/laws/regulations/fur-harvester","note":"Cross-reference row from the sweep's Cat 3 table; verification inherited from the live-verified Cat 2 entry."},{"category":5,"rule":"Combined-row finding: permission required before trapping private land, but sampled guides do not specify it must be written — code as permission-yes / written-unspecified","deadline":null,"source":"https://www.michigan.gov/dnr/managing-resources/laws/regulations/fur-harvester","note":"The sweep's Cat 5 combined row (WI MI VT VA IL NE WA) cited only two URLs (WI DNR and the WA WDFW pamphlet) for all seven states. For this state the source given is the state's own official guide page cited elsewhere in the sweep; no state-specific Cat 5 URL was provided."},{"category":6,"rule":"Contrast: no mandatory statewide trapper education (DNR was developing a course; FAQ describes none mandatory)","deadline":null,"source":"https://animalofthings.com/trapping-laws-in-michigan/"},{"category":7,"rule":"Nonresidents may not harvest badger, bobcat, fisher, marten or otter at all (other furbearers allowed with a fur harvester licence)","deadline":null,"source":"https://www.michigan.gov/dnr/managing-resources/laws/regulations/fur-harvester"},{"category":9,"rule":"Otters incidentally taken while beaver trapping through Apr 30 count toward the otter bag limit (register by May 5); otters over the bag limit may not be kept — submit to DNR under incidental-catch rules; printed incidental kill tags introduced 2026","deadline":"May 5 (incidental otter registration)","source":"https://www.michigan.gov/dnr/managing-resources/laws/regulations/fur-harvester"}];
window.OPOSSUM_FOOT_GAP_DATA["MN"] = [{"category":1,"rule":"Trap/snare on land you don't own/occupy must carry driver's licence no., MN ID, name+mailing address, or DNR licence ID (Minn. Stat. 97B.928)","deadline":null,"source":"https://www.dnr.state.mn.us/hunting/trapping/index.html"},{"category":2,"rule":"Bobcat, fisher, pine marten, otter, wolf pelts presented for registration before sale / out-of-state transport and no more than 48 hours after season closes; wolf whole carcass also presented (Stat. 97B.901)","deadline":"48 hours after season closes","source":"https://www.revisor.mn.gov/statutes/2018/cite/97B.901"},{"category":3,"rule":"Fisher/marten/bobcat registration no more than 48 hours after season close (and before sale or removal from state); river otter may be registered through May 17, 2027","deadline":"48 hours after season close; otter through May 17, 2027","source":"https://www.dnr.state.mn.us/hunting/trapping/index.html","note":"Confirmed on the cited MN DNR page, incl. 'River otter may be registered through May 17, 2027.'"},{"category":4,"rule":"Possession becomes unlawful in effect after the Cat 2 registration deadline passes with the pelt unregistered — see the Category 2 entry for this state","deadline":"48 hours after season closes","source":"https://www.revisor.mn.gov/statutes/2018/cite/97B.901","note":"Combined-row entry from the sweep's Cat 4 table ('possession unlawful in effect after sealing deadline'); verification inherited from the live-verified Cat 2 entry."},{"category":6,"rule":"Born after Dec 31, 1989 and never previously licensed: no trapping licence without a trapper-education certificate (incl. mandatory field training)","deadline":null,"source":"https://www.dnr.state.mn.us/hunting/trapping/index.html","note":"Also confirmed live on the cited MN DNR page during Cat 3 verification ('Persons born after Dec. 31, 1989... may not obtain a trapping license without a trapper education certificate')."},{"category":9,"rule":"Incidental Canada lynx: report to a conservation officer within 24 hours whether released or dead; may not possess/transport dead lynx/wolf without prior authorisation; accidental fisher/otter/marten/bobcat kills: notify officer before skinning/transfer/disposal (Minn. Rules 6234.2700)","deadline":"24 hours (incidental lynx report)","source":"https://www.revisor.mn.gov/rules/6234.2700/version/2014-01-18T06:51:40-06:00"},{"category":10,"rule":"Snares capable of taking a wild animal (except under-ice, and licensed wolf trappers in wolf season): breakaway disassembling at 350 lb static pull or less; loop max 10 in dia., top of loop max 20 in above ground, cable max 1/8 in; snares banned in deer/elk/moose trails","deadline":null,"source":"https://www.dnr.state.mn.us/hunting/trapping/snare-breakaway-requirements.html"}];
window.OPOSSUM_FOOT_GAP_DATA["MO"] = [{"category":2,"rule":"Bobcats & otters / pelts delivered to Conservation agent for registration/tagging before selling, transferring, tanning or mounting, by Apr 10; illegal to buy/sell untagged","deadline":"April 10","source":"https://mdc.mo.gov/hunting-trapping/regulations"},{"category":3,"rule":"Per-animal harvest reporting is embedded in the pelt tagging/sealing requirement — see the Category 2 entry for this state","deadline":"April 10","source":"https://mdc.mo.gov/hunting-trapping/regulations","note":"Cross-reference row from the sweep's Cat 3 table; verification inherited from the live-verified Cat 2 entry."},{"category":4,"rule":"Tagged bobcat/otter pelts may be possessed by the taker throughout the year; untagged pelts may not be bought or sold","deadline":null,"source":"https://mdc.mo.gov/hunting-trapping/regulations","note":"Confirmed live on the MDC regulations pages during Cat 2 verification (tagged pelts possessable all year)."},{"category":10,"rule":"Cable restraints (land): stranded cable max 5 ft, min 5/64 in, commercial breakaway rated 350 lb or less, relaxing-type lock, stop preventing closure under 2.5 in, anchor swivel; compression chokes/power springs prohibited. True snares: underwater only, loop max 15 in, stop under 2.5 in, mechanical lock + swivel","deadline":null,"source":"https://mdc.mo.gov/hunting-trapping/regulations"},{"category":12,"rule":"Excessive waste: illegal to intentionally leave/abandon any portion of wildlife commonly used as human food; furbearer dens/nests must not be molested/destroyed; skinned furbearer carcasses may be sold year-round","deadline":null,"source":"https://mdc.mo.gov/hunting-trapping/regulations"}];
window.OPOSSUM_FOOT_GAP_DATA["MS"] = [{"category":3,"rule":"Trapper harvest survey return deadline May 1","deadline":"May 1","source":"https://animalofthings.com/trapping-laws-in-mississippi/","note":"Verified on the sweep's cited page: 'The deadline for returning trapper harvest surveys is May 1.'"},{"category":4,"rule":"Licensed trapper may sell/consign raw fur, green & dried pelts during the season and 30 days after close; transport of raw/green pelts barred from 11 days after close until next opener unless each is tagged/documented with harvester name/address/ID + date/place; storage possession allowed anytime (Miss. Code 49-7-13(6))","deadline":"Season + 30 days to sell/consign; transport barred from day 11 after close unless documented","source":"https://law.justia.com/codes/mississippi/2019/title-49/chapter-7/in-general/section-49-7-13/","note":"Confirmed verbatim in the statute text read live (subsections (6)(a)-(c))."}];
window.OPOSSUM_FOOT_GAP_DATA["MT"] = [{"category":2,"rule":"Bobcat, otter, fisher, marten, wolf, swift fox: personal report + pelt presented to FWP for tagging; wolf hide+skull unfrozen within 10 days of harvest; fisher entire intact carcass turned in at tagging","deadline":"Wolf: 10 days after harvest; report within 24 hours","source":"https://fwp.mt.gov/binaries/content/assets/fwp/hunt/regulations/2026/2026-wolf-and-furbearer-final-for-web.pdf"},{"category":3,"rule":"Bobcat, fisher, marten, otter, swift fox (+ wolf) personally reported within 24 hours by phone/online so FWP can monitor quotas; backcountry: within 24 hours of reaching trailhead","deadline":"24 hours after harvest","source":"https://fwp.mt.gov/binaries/content/assets/fwp/hunt/regulations/2026/2026-wolf-and-furbearer-final-for-web.pdf","note":"Sweep cited an FWP commission changes PDF; verified in FWP's 2026 wolf & furbearer regulations PDF ('bobcat, fisher, marten, otter, and/or swift fox harvests within 24 hours')."},{"category":4,"rule":"Possession becomes unlawful in effect after the Cat 2 tagging deadline passes with the pelt untagged — see the Category 2 entry for this state (wolf hide/skull within 10 days of harvest)","deadline":"Wolf: 10 days after harvest","source":"https://fwp.mt.gov/binaries/content/assets/fwp/hunt/regulations/2026/2026-wolf-and-furbearer-final-for-web.pdf","note":"Combined-row entry from the sweep's Cat 4 table; verification inherited from the live-verified Cat 2 entry. Contrast the separate MT Cat 4 entry: MCA 87-6-602 otherwise allows possession of legally taken furs at any time."},{"category":4,"rule":"Contrast: furs/hides legally taken in open season may be possessed, bought and sold at any time (MCA 87-6-602); dealer may not buy/possess untagged bobcat/otter/fisher/marten/wolverine","deadline":null,"source":"https://animalofthings.com/trapping-laws-in-montana/","note":"Verified on the cited page: 'MCA 87-6-602 allows furs and hides of fur-bearing animals legally taken in open season to be possessed, bought, and sold at any time, except as provided by law.'"},{"category":6,"rule":"Species-specific: wolf trapping requires a one-time wolf-trapping certification course (ID course accepted for nonresidents); general trapper ed is effectively bypassed after 3 lifetime trapping licences from any state","deadline":null,"source":"https://animalofthings.com/wolf-hunting-season-in-montana-2026-27/"},{"category":9,"rule":"Capture of any animal that cannot be lawfully trapped, including domestic animals, must be reported to FWP within 24 hours; uninjured animals must be released before leaving the trap site; injured/dead: report promptly for disposition","deadline":"24 hours (non-target report)","source":"https://fwp.mt.gov/binaries/content/assets/fwp/hunt/regulations/2026/2026-wolf-and-furbearer-final-for-web.pdf","note":"Also corroborated in the FWP 2026 PDF read live during Cat 2-4 verification (multiple 'reported to FWP within 24 hours' provisions for non-target captures)."},{"category":11,"rule":"Wolf traps: setback along open roads / signed hiking trails (150 ft in FWP materials) and a larger setback from trailheads/campgrounds","deadline":null,"source":"https://fwp.mt.gov/binaries/content/assets/fwp/hunt/regulations/2026/2026-wolf-and-furbearer-final-for-web.pdf","note":"Sweep flags: exact 2026-27 wolf-trap setback distances were not extracted line-by-line in the sweep — verify exact figures in the FWP PDF before coding."},{"category":12,"rule":"MCA 87-6-603: may not waste a furbearing animal by failing to pick up traps/snares at season end so the pelt is wasted, attending traps so a furbearer is wasted, or wasting the pelt of any furbearing animal","deadline":null,"source":"https://fwp.mt.gov/binaries/content/assets/fwp/commission/2026/sep-24/trap-check-comments/uploaded-trap-check-comments.pdf"},{"category":12,"rule":"Carcass surrender: fisher — the entire intact carcass must be turned in to FWP at pelt tagging; wolf collar must be returned within 10 days / FWP notified within 24 hours if a wolf is left in the field","deadline":"Wolf collar return 10 days; fisher carcass at tagging","source":"https://fwp.mt.gov/binaries/content/assets/fwp/hunt/regulations/2026/2026-wolf-and-furbearer-final-for-web.pdf","note":"Fisher carcass turn-in also appears in the FWP 2026 PDF read live during Cat 2 verification ('Carcasses — It is mandatory that the entire and intact carcass of [fisher]...')."}];
