window.OPOSSUM_FOOT_GAP_DATA["OK"] = [{"category":2,"rule":"No bobcat/otter pelt held more than 10 working days after season close, sold, bartered or taken out of OK without a permanent (export) tag affixed by Dept/designated agent; tags will not be affixed after Mar 12","deadline":"10 working days after season close; no tags affixed after March 12","source":"https://www.wildlifedepartment.com/hunting/regs/furbearercoyote-regulations"},{"category":3,"rule":"Per-animal harvest reporting is embedded in the pelt tagging/sealing requirement — see the Category 2 entry for this state","deadline":"10 working days after season close; no tags affixed after March 12","source":"https://www.wildlifedepartment.com/hunting/regs/furbearercoyote-regulations","note":"Cross-reference row from the sweep's Cat 3 table; verification inherited from the live-verified Cat 2 entry."},{"category":4,"rule":"ODWC version: persons taking pelts have 10 working days after season close to sell/dispose of them, or notify the Dept in writing of intent to hold; held pelts must be inventoried on a Dept form; bobcat/otter must be tagged before holding","deadline":"10 working days after season close","source":"https://www.wildlifedepartment.com/hunting/regs/furbearercoyote-regulations","note":"CONFLICT (see the second OK Cat 4 entry): the OAC text at Cornell, sec. 800:25-7-60(6), gives 'until the end of March' for the same sell/dispose-or-notify duty. Both versions recorded per instructions; the two sources genuinely differ for the general pelt rule (the OAC's 10-working-day figure appears in its bobcat/otter tag subsection (2)(A))."},{"category":4,"rule":"OAC version: any person who takes a pelt or pelts during the season has until the end of March to sell or dispose of the pelts or provide written notification to the Dept of intent to hold them for later sale, on a Dept form (OAC 800:25-7-60(6))","deadline":"End of March","source":"https://www.law.cornell.edu/regulations/oklahoma/OAC-800-25-7-60","note":"CONFLICT (see the first OK Cat 4 entry): ODWC's regulations page states 10 working days after season close for sell/dispose-or-notify. The OAC text read live at Cornell states 'until the end of March' in its Intent to hold subsection (6), while its bobcat/otter tag subsection (2)(A) uses 10 working days. Unresolved which deadline ODWC enforces for general pelts."},{"category":8,"rule":"NWCO permit = certification (National Wildlife Control Training Program course) + annual permit; authorises year-round, no-limit take of designated species for nuisance complaints; traps checked 24h, tagged with operator name + NWCO permit no.; sale/retention of NWCO-taken wildlife prohibited except coyote/beaver","deadline":null,"source":"https://wildlifedepartment.com/law/nwco-operators/additional-info"},{"category":12,"rule":"Skinned carcasses/parts of legally taken furbearers & coyotes (excluding hide/pelt) may be sold/bartered at any time; scent glands may be sold","deadline":null,"source":"https://www.wildlifedepartment.com/hunting/regs/furbearercoyote-regulations","note":"Also stated verbatim in OAC 800:25-7-60(1), read live during Cat 4 verification: 'The skinned carcass of any legal furbearer or predator may be sold... at any time. The sale of scent glands... is permitted.'"}];
window.OPOSSUM_FOOT_GAP_DATA["OR"] = [{"category":1,"rule":"All traps/snares legibly marked/branded with owner's Dept-assigned licence (brand) number; own-land nongame exception (OAR 635-050-0045(4))","deadline":null,"source":"https://regulations.justia.com/states/oregon/chapter-635/division-50/section-635-050-0045/","note":"Brand-number rule also read live in ODFW Division 050 rule text during Cat 2-4 verification."},{"category":2,"rule":"Bobcat and river otter record card must be purchased before hunting/trapping and carried on person; harvest recorded on the card immediately; pelt must receive a Dept ownership tag (lower jaw surrendered) within 5 business days after the season ends; possession after that without a tag is unlawful (OAR 635-050-0180, 635-050-0183)","deadline":"Ownership tag within 5 business days after season ends","source":"https://dfw.state.or.us/agency/commission/minutes/20/06_Jun/EXHIBIT E/Exhibit E_Attachment 4_Draft Oregon Administrative Rule.pdf","note":"Sweep cited the Justia OAR 635-050-0045 page, which returned only a chapter index with no rule text; verified instead on ODFW's own Division 050 rule text (record cards sec. 635-050-0180; ownership tags sec. 635-050-0183). The sweep's one-liner mentioned only the record card; the live rule text adds the 5-business-day ownership-tag deadline."},{"category":3,"rule":"Every furtaker / hunting-for-furbearer licence holder must submit the Furtaker Harvest Report postmarked/submitted by Apr 15; failure = cannot buy next year's licence unless late report filed + $50 fee. Per-beaver location/ownership/reason detail required","deadline":"April 15","source":"https://myodfw.com/articles/furbearer-trapping-and-hunting","note":"Confirmed on the cited ODFW page: report 'postmarked by April 15, 2027 for the 2026-2027 season'; failure blocks next licence unless late report + $50.00 fee. Same April 15 + $50 rule also in OAR 635-050-0045(2)."},{"category":5,"rule":"Nuance: possessing another person's branded traps/snares requires written permission from the brand registrant (OAR 635-050-0045)","deadline":null,"source":"https://regulations.justia.com/states/oregon/chapter-635/division-50/section-635-050-0045/","note":"Also read live in ODFW Division 050 rule text during Cat 2-4 verification (635-050-0045(9)(f))."},{"category":6,"rule":"All first-time Oregon trappers must complete an approved trapper education course incl. knowledge test (not required when trapping on land you own/lease; juveniles under 12 need the course to trap bobcat/river otter)","deadline":null,"source":"https://myodfw.com/articles/furbearer-trapping-and-hunting","note":"Not a sweep Cat 6 row — added because the ODFW page read live during Cat 3 verification states this requirement plainly and the sweep's Cat 6 list omits OR. Flagged here rather than dropped."},{"category":7,"rule":"Contrast — allowed, price-gated only: nonresident Furtaker's License $456 vs resident $61","deadline":null,"source":"https://myodfw.com/articles/furbearer-trapping-and-hunting","note":"The sweep's Cat 7 contrast row cited only the AK and TX URLs; fees confirmed live on the ODFW page read during Cat 3 verification (Resident Furtaker $61.00 / Nonresident Furtaker $456.00)."},{"category":12,"rule":"Unlawful to waste the pelt of any furbearer taken when authorised by ODFW (OAR 635-050-0045(17)); raw-pelt transfers must be accompanied by a written record of the source name/address while the pelt is in raw form","deadline":null,"source":"https://dfw.state.or.us/agency/commission/minutes/20/06_Jun/EXHIBIT E/Exhibit E_Attachment 4_Draft Oregon Administrative Rule.pdf","note":"Sweep cited an ODFW permanent-filing PDF; the waste rule was read live in ODFW's Division 050 rule text during Cat 2-4 verification (635-050-0045(17): 'It is unlawful to waste the pelt of any furbearer'), so that document is the source given."}];
